UPDATE public.landing_content SET content = '{"faq": {"items": [{"id": "q1", "q": "Preciso instalar alguma coisa?", "a": "Não. FitJourney é 100% web e PWA. Funciona no navegador e pode ser instalado como app no celular do paciente."}, {"id": "q2", "q": "Meus pacientes precisam pagar?", "a": "Não. Apenas o profissional paga pelo plano. Pacientes acessam gratuitamente por convite."}, {"id": "q3", "q": "A IA do FitJourney substitui o nutricionista?", "a": "Jamais. O FitJourney trabalha com inteligência própria, determinística e auditável — não é um LLM opinando. O sistema acelera decisões com dados reais (TDEE, macros, matcher de template), mas a decisão clínica é sempre sua. É semi-automático: você decide, ele executa com precisão."}, {"id": "q4", "q": "Como funciona o financeiro?", "a": "Você controla assinaturas e pagamentos avulsos manualmente dentro da plataforma, com dashboard de MRR/ARR, ticket médio e receita por período. Integração com gateways automáticos (Stripe, Pix, Mercado Pago) está no roadmap."}, {"id": "q5", "q": "Meus dados estão seguros?", "a": "Sim. Criptografia de ponta, Row-Level Security e LGPD completo: consentimento versionado, exportação e exclusão sob demanda."}, {"id": "q6", "q": "Posso personalizar com minha marca?", "a": "Sim. No plano Pro você personaliza cores, logo e identidade visual. O paciente vê o seu consultório, não o nosso."}, {"id": "q7", "q": "Tem suporte?", "a": "Sim. Chat in-app e email para todos. Suporte prioritário no plano Pro."}], "title": "Perguntas frequentes", "eyebrow": "FAQ", "visible": true}, "hero": {"badge": "Para nutricionistas · Plataforma clínica", "cta_primary": "Começar 3 dias grátis →", "description": "Não se trata de montar dietas mais rápido. Trata-se de conduzir o metabolismo humano com precisão — com cada decisão registrada, auditável e reproduzível. Você constrói protocolos. A plataforma faz o resto.", "title_line1": "A evolução da", "title_line2": "Nutrição Clínica Inteligente.", "trust_items": ["Sem cartão de crédito", "Acesso imediato", "Pacientes por convite"], "cta_secondary": "Ver o que você pode fazer", "hero_media_url": "", "hero_media_type": "logo-orbital"}, "stats": {"items": [{"id": "s1", "value": "100%", "label": "Soberania clínica"}, {"id": "s2", "value": "V3", "label": "Snapshot imutável"}, {"id": "s3", "value": "TACO", "label": "Base alimentar BR"}, {"id": "s5", "value": "3 dias", "label": "Trial sem cartão"}], "visible": true}, "pricing": {"plans": [{"id": "basic", "name": "Basic", "price": "R$ 39,90", "period": "/mês", "popular": false, "cta": "Começar 3 dias grátis →", "features": ["Até 30 pacientes ativos", "Anamnese v2 + prontuário clínico", "Editor de planos + Smart Templates BR", "Avaliação física completa (TMB/TDEE)", "Feedbacks quinzenais automatizados", "App PWA com sua marca", "Perfil público /n/slug + convite curto"]}, {"id": "pro", "name": "Pro", "price": "R$ 74,90", "period": "/mês", "popular": true, "cta": "Começar 3 dias grátis →", "features": ["Pacientes ilimitados", "Protocolo FitJourney™ (motor clínico determinístico)", "Template Matcher automático por contexto clínico", "Snapshot V3 imutável + auditoria clínica", "Dashboard financeiro (MRR/ARR, ticket médio)", "Busca global + insights de aderência", "LGPD completo (consentimento, exportação, exclusão)", "Branding personalizado + suporte prioritário"]}], "eyebrow": "Planos", "visible": true, "description": "3 dias grátis. Sem cartão de crédito. Acesso imediato ao sistema completo.", "title_line1": "Comece grátis.", "title_line2": "Cresça sem surpresas."}, "features": {"items": [{"id": "f1", "icon": "FileText", "tag": "Atendimento Clínico", "title": "Anamnese v2 com alertas automáticos", "desc": "Coleta guiada, alertas clínicos automáticos e fila de revisão. O prontuário fica pronto para consulta, sem PDFs avulsos."}, {"id": "f2", "icon": "BarChart3", "tag": "Atendimento Clínico", "title": "Avaliação física completa", "desc": "Dobras (Jackson-Pollock 7), circunferências, composição corporal, IMC, TMB e TDEE calculados automaticamente a partir dos dados reais do paciente."}, {"id": "f3", "icon": "Shield", "tag": "Atendimento Clínico", "title": "Protocolo FitJourney™", "desc": "Motor clínico determinístico e auditável: cada decisão é registrada, reproduzível e defensável. Inteligência própria do sistema — sem caixa-preta, sem palpite."}, {"id": "f4", "icon": "Utensils", "tag": "Planos Alimentares", "title": "Editor clínico soberano", "desc": "Monte, edite e publique planos por dia/refeição com metas de macros calculadas pelo motor. O que você publica é exatamente o que o paciente recebe."}, {"id": "f5", "icon": "Sparkles", "tag": "Planos Alimentares", "title": "Smart Templates BR", "desc": "Biblioteca de templates clínicos com base TACO, prontos para clonar, ajustar e publicar em minutos."}, {"id": "f6", "icon": "Brain", "tag": "Planos Alimentares", "title": "Template Matcher automático", "desc": "O sistema sugere o template ideal a partir do contexto clínico do paciente (objetivo, TDEE, restrições). Semi-automático: você decide, ele acelera."}, {"id": "f7", "icon": "Lock", "tag": "Planos Alimentares", "title": "Snapshot V3 imutável", "desc": "Depois de publicado, o plano é congelado. Nada é recalculado no celular do paciente, nada muda sem o seu aval. Adesão sobe porque a entrega é confiável."}, {"id": "f8", "icon": "Smartphone", "tag": "App do Paciente", "title": "App PWA com sua marca", "desc": "O paciente acessa o plano congelado, histórico clínico e prescrições direto do celular, com a identidade visual do seu consultório."}, {"id": "f9", "icon": "LineChart", "tag": "App do Paciente", "title": "Feedbacks quinzenais + gráfico real", "desc": "Peso, foto e aderência com countdown automático. Evolução visual semana a semana — dados reais, projeções reais, sem promessas fantasiosas."}, {"id": "f10", "icon": "ShieldCheck", "tag": "App do Paciente", "title": "LGPD completo", "desc": "Consentimento versionado, exportação e exclusão de dados. Conformidade clínica e jurídica de ponta a ponta."}, {"id": "f11", "icon": "Link2", "tag": "Gestão", "title": "Perfil público + convite curto", "desc": "Página /n/seu-slug otimizada para conversão e link /c/slug para captar pacientes em qualquer canal (Instagram, WhatsApp, bio)."}, {"id": "f12", "icon": "DollarSign", "tag": "Gestão", "title": "Financeiro do consultório", "desc": "Controle de assinaturas, ticket médio, MRR/ARR e receita por período. Registro manual de pagamentos com visão clara do caixa."}, {"id": "f13", "icon": "Search", "tag": "Gestão", "title": "Busca global + insights de aderência", "desc": "Encontre qualquer paciente, anamnese ou plano em segundos. Timeline clínica e insights de aderência para decisões rápidas."}, {"id": "f14", "icon": "Clock", "tag": "Gestão", "title": "Trial 3 dias + paywall", "desc": "Teste a plataforma completa por 3 dias sem cartão. Depois, planos transparentes e cancelamento em 1 clique."}, {"id": "f15", "icon": "Camera", "tag": "Em breve", "title": "Avaliação física por foto", "desc": "Análise de evolução corporal a partir de fotos do paciente. Em desenvolvimento."}, {"id": "f16", "icon": "Utensils", "tag": "Em breve", "title": "Avaliação de prato por foto", "desc": "Reconhecimento de refeição e estimativa de macros via foto. Em desenvolvimento."}], "eyebrow": "Plataforma", "visible": true, "description": "Tudo que o consultório de nutrição moderno precisa — organizado em quatro pilares que conversam entre si, sem retrabalho e sem caixa-preta.", "title_line1": "Quatro pilares.", "title_line2": "Uma única plataforma."}, "obstacle": {"cards": [{"id": "c1", "desc": "Análise completa do metabolismo do paciente — não estimativas genéricas. Você prescreve considerando TMB, TDEE, composição corporal e resposta fisiológica individual.", "tone": "primary", "title": "Planos baseados no metabolismo real", "consequence": "Plano 100% personalizado por paciente."}, {"id": "c2", "desc": "Feedbacks quinzenais automatizados, histórico clínico vivo e visibilidade contínua do progresso. Seu paciente nunca fica solto entre consultas.", "tone": "gold", "title": "Acompanha cada paciente sem viver no WhatsApp", "consequence": "Vínculo clínico além da consulta."}, {"id": "c3", "desc": "Gráficos de progresso corporal, comparativo de fotos e marcos de evolução visíveis — baseados em dados reais, não em projeções fantasiosas.", "tone": "primary", "title": "Vê o corpo evoluindo semana a semana", "consequence": "Decisão clínica baseada em evidência."}], "eyebrow": "O que você faz com o FitJourney", "visible": true, "description": "Com avaliação clínica completa, acompanhamento estruturado e decisão auditável, o sistema transforma cada paciente em uma jornada conduzida — não em um plano entregue e esquecido.", "footer_text": "Não buscamos transformações relâmpago. Buscamos mudanças duradouras.", "title_line1": "Muito além de um", "title_line2": "plano alimentar."}, "final_cta": {"title": "Mais ciência. Mais estratégia. Mais resultado real.", "visible": true, "cta_primary": "Criar minha conta agora →", "description": "3 dias grátis. Sem cartão de crédito. Acesso imediato ao sistema completo.", "cta_secondary": "Explorar a plataforma"}, "testimonials": {"items": [{"id": "t1", "name": "Dra. Ana Costa", "role": "Nutricionista Esportiva", "text": "Saí de prescritora reativa para gestora estratégica do metabolismo. Cada decisão registrada, auditável.", "avatar": "AC", "rating": 5}, {"id": "t2", "name": "Dr. Carlos Silva", "role": "Nutricionista Clínico", "text": "Fui de 80 para 143 pacientes ativos sem contratar ninguém. O tempo por plano caiu de 1h para 12 minutos.", "avatar": "CS", "rating": 5}, {"id": "t3", "name": "Dra. Mariana Luz", "role": "Nutricionista Funcional", "text": "Antes eu publicava em PDF e rezava. Hoje o plano é o mesmo no meu painel e no celular do paciente — congelado, auditável.", "avatar": "ML", "rating": 5}, {"id": "t4", "name": "Dr. Rafael Mendes", "role": "Nutricionista Comportamental", "text": "